import{_ as t,o,c as u,ag as q}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第82章 以前的同学","description":"","frontmatter":{},"headers":[],"relativePath":"第82章_以前的同学.md","filePath":"第82章_以前的同学.md"}'),e={name:"第82章_以前的同学.md"};function a(_,p,r,n,s,c){return o(),u("div",null,[...p[0]||(p[0]=[q('<h1 id="第82章-以前的同学" tabindex="-1">第82章 以前的同学 <a class="header-anchor" href="#第82章-以前的同学" aria-label="Permalink to &quot;第82章 以前的同学&quot;">​</a></h1><p>她那边有人开始知道我了。</p><p>不是因为她说出来。</p><p>是因为我存在于她的屏幕上。</p><p>十一月初有一天，她上线晚了。</p><p>平时她那边下午五点，那天她七点才上来。</p><p>她说，我今天被问了一件事。</p><p>我说，谁问。</p><p>她说，我室友。</p><p>她说，她从我背后看见我在打字。</p><p>她说，她问我，你在跟谁讲。</p><p>我说，你怎么说。</p><p>她说，我说一个同学。</p><p>我说，哪个同学。</p><p>她说，她说，你哪来这么多同学。</p><p>她说，我说，以前的。</p><p>我看到&quot;以前的&quot;那三个字，坐在那儿。</p><p>我后来把这三个字拆开看了很久。</p><p>以前的同学。</p><p>这个说法没有一处谎。</p><p>我确实是同学。</p><p>它也没有一处真。</p><p>因为它的意思是我们已经过去了。</p><p>我给她回了一句。</p><p>我说，你以前有很多同学。</p><p>她说，你听出来了。</p><p>我说，我听得出来。</p><p>她说，我那天讲完这句我自己愣了一下。</p><p>我说，愣什么。</p><p>她说，因为我讲得特别顺。</p><p>她说，我说&quot;以前的同学&quot;这四个字，跟说&quot;今天下雨&quot;一样快。</p><p>她说，说明我在心里已经把这件事摆好了。</p><p>她说，我把它摆到&quot;以前的&quot;那一格，我才讲得出来。</p><p>我说，那你为什么把我摆到那一格。</p><p>她说，因为那一格不用解释。</p><p>她说，我要是说&quot;我一个朋友&quot;，她第二天就会问是谁，叫什么，在哪儿。</p><p>她说，我要是说&quot;我在谈恋爱&quot;，她要问我谈了几年，我妈知不知道。</p><p>她说，我要是说&quot;我在等一个人&quot;，我室友要哭。</p><p>她说，我这边最怕的是有人为我哭。</p><p>她说，一有人为我哭，我就得对她好。</p><p>她说，我这一辈子欠的哭太多了，我不能再欠。</p><p>我说，那&quot;以前的同学&quot;就不欠了？</p><p>她说，&quot;以前的同学&quot;是一个已经过去了的东西。</p><p>她说，过去了的东西不用谁负责。</p><p>我说，那我在哪儿。</p><p>她说，你在这儿。</p><p>她说，你在这个号上。</p><p>她说，这个号上没有&quot;以前&quot;。</p><p>她说，这个号上我说的是&quot;我在跟一个人讲话&quot;，我不加以前。</p><p>我说，那你跟你室友为什么要加。</p><p>她说，因为她活在她的时间里。</p><p>她说，我要是让她看见我这边还有一个正在进行的、没有名字的东西，她今天这一天就过不好。</p><p>她说，我是在替她省事。</p><p>我说，那你也是替你自己省事。</p><p>她说，对。</p><p>她说，我不否认这一句。</p><p>那件事以后，我这边开始留意一个我以前从来没想过的问题。</p><p>我在这个世界上的哪一个记录里存在。</p><p>我拿这件事认真想了一遍。</p><p>我的班级群里，有我的名字。</p><p>我家里那个户口本上有我的名字。</p><p>她那个城市的派出所里，有她家的地址，没有我。</p><p>她那边的学校档案里，没有我。</p><p>她妈知道有一个人在等她女儿，她妈不知道我是谁。</p><p>她室友知道有一个&quot;以前的同学&quot;。</p><p>她的朋友里只有何叶知道我叫什么，因为何叶跟我是同班。</p><p>而我这边的六个人，只知道我每天晚上对着一台手机笑。</p><p>郑拓有一天问我，你跟谁讲。</p><p>我说，一个同学。</p><p>他说，哪个同学。</p><p>我说，以前的。</p><p>我说完这三个字，我自己停了一下。</p><p>我发现我讲得也很顺。</p><p>我那天夜里在本子上写了一件事。</p><p>我写：我们两个在各自那边，用的是同一个说法。</p><p>我写：以前。</p><p>我写：这个说法不需要商量，因为它两边都假，两边都省事。</p><p>我写：假话这个东西，只要两边讲得一样，它就变成一个秘密。</p><p>那年十二月有一件事，让这个名字第一次漏出去。</p><p>她那边有一个小的线上分享，她讲她的图。</p><p>她讲完有一页放的是她桌上那张纸。</p><p>那张纸是我三月寄给她的——不是画，是我抄她&quot;以后&quot;的那张纸的复印件。</p><p>她拿去垫在杯子底下。</p><p>那张纸的右下角，我写过一个字。</p><p>我写的是一个&quot;闻&quot;。</p><p>我给她寄的时候，我以为我抄的是她的话，我署我的姓，这是应该的。</p><p>那天分享结束，有人在下面评论。</p><p>那个人问：你杯子底下那张纸上有个字，是谁写的。</p><p>她回：一个朋友。</p><p>那个人说：哦。</p><p>她说，就一个&quot;哦&quot;。</p><p>她说，可是那天晚上我室友问我，那个朋友是谁。</p><p>我说，你怎么说。</p><p>她说，我说，一个还没丢掉的人。</p><p>我说，你什么时候学会讲这种话。</p><p>她说，我刚才想的。</p><p>她说，我讲完我自己吓了一跳。</p><p>她说，因为我讲的那句话里，你在。</p><p>她说，而且我把它放在&quot;人&quot;这个字上面了。</p><p>我说，那我是什么。</p><p>她说，你是一个还在的东西。</p><p>她说，闻迟，你不要拆我。</p><p>她说，我这一辈子只能讲到这一步。</p><p>那天晚上我下线很早。</p><p>我不是生气。</p><p>我是怕我再问一句，她就收回去。</p><p>她收回去我会记住十年。</p><p>二月有一件事，把这三个字送到了我自己身上。</p><p>那年过年我在家，我妈一个妹妹来。</p><p>她带了她女儿，上初三，一进屋就抱着一台手机笑。</p><p>她小姨问我，你现在在学校有没有处一个。</p><p>我妈在边上那个洗苹果的声音一下停了。</p><p>我说，没有。</p><p>她说，你妈说你天天晚上对着手机。</p><p>我说，我看作业。</p><p>她小姨说，看作业看那么晚。</p><p>我妈把苹果放到盘里，拿布擦了一下手。</p><p>她说，他现在忙。</p><p>她说，他有个以前的同学，在很远的地方，他们那个小组要做东西。</p><p>我说，妈。</p><p>她说，怎么了，我说错了吗。</p><p>她说，你不是自己讲的吗，以前那个同学，不在我们这边。</p><p>那天晚上我一个人在房间里坐着。</p><p>我妈那句话说得很自然。</p><p>自然到我听出来她练过。</p><p>她练了很多次。</p><p>因为家里所有人问这个问题，她都要答。</p><p>她答的那个版本里，我没有喜欢的人，我有一个以前的同学。</p><p>我妈把这件事讲成了一个小组作业。</p><p>因为她不知道还能把它讲成什么。</p><p>她知道有一个人，她不知道那个人是谁，她连那个人的名字都没听过。</p><p>她只看见她儿子每个月买一块钱的邮票、存一个本子、晚上十一点不出声。</p><p>那天夜里我给何叶发了一条消息。</p><p>我那时候不知道我为什么要找她。</p><p>我只知道她是唯一一个知道我姓什么的人在她那边。</p><p>我发的是：她跟你讲过我的事吗。</p><p>何叶隔了十分钟。</p><p>她说：没有。</p><p>她说：她连我都没讲。</p><p>她说：她只跟我借过一次钱，那次她讲了你的名字。</p><p>她说：她说你有个同学，帮你发个东西。</p><p>她说：我当时想，她什么都有人肯帮她发货。</p><p>我把手机放下。</p><p>那天夜里我在本子上写了三行。</p><p>我写：我妈把他说成了一个小组作业。</p><p>我写：她把我妈的提问接得很顺，因为她练过。</p><p>我写：我们两边各自把这个人说小了一点，说到最后，它就不存在了。</p>',147)])])}const l=t(e,[["render",a]]);export{d as __pageData,l as default};
